export type DoomSwipingProps = Record<string, any>;

// ------------------------------------------------------------------
// HELPERS
// ------------------------------------------------------------------

const SKINTONES = ["#f8d9ce", "#f4c6b2", "#e0ac69", "#8d5524", "#513931", "#ffdbac"];
const HAIR_COLORS = ["#000000", "#4a4a4a", "#8b4513", "#d2691e", "#e6be8a", "#a52a2a"];

const getRandomItem = (arr: any[], seed: number) => {
  return arr[Math.floor(random(seed) * arr.length)];
};

const generateProfile = (index: number, colors: string[]) => {
  const seed = index * 1234;
  const gender = random(seed) > 0.5 ? "female" : "male";
  
  return {
    id: index,
    name: "Person " + index, // Placeholder, no text rendering requested essentially
    bg: getRandomItem(colors, seed),
    skin: getRandomItem(SKINTONES, seed + 1),
    hair: getRandomItem(HAIR_COLORS, seed + 2),
    gender,
    hasGlasses: random(seed + 3) > 0.7,
    hasHat: random(seed + 4) > 0.8,
    action: random(seed + 5) > 0.8 ? "fake-right" : "left", // 20% chance to fake right
  };
};

