const ActionButtons: React.FC<{
  activeIndex: number;
  swipeSpeed: number;
  profiles: any[];
}> = ({ activeIndex, swipeSpeed, profiles }) => {
  const frame = useCurrentFrame();
  
  // Animate buttons based on the rhythm of the swipes
  // Each swipe completes at (index+1)*swipeSpeed
  // We want a punch effect right when the swipe initiates or completes?
  // Let's punch when the swipe starts (rejection click)
  
  const currentProfile = profiles[activeIndex];
  
  // Calculate local progress of current swipe
  const startFrame = activeIndex * swipeSpeed;
  const progress = interpolate(frame, [startFrame, startFrame + swipeSpeed], [0, 1], {
      extrapolateLeft: 'clamp', 
      extrapolateRight: 'clamp'
  });
  
  // Trigger punch at start of swipe
  const isPunching = progress < 0.3;
  
  // If action is left, punch X. If action is right (fake), punch Check/Heart briefly then X?
  // The prompt says "Icons flash briefly, then vanish. X icons pulse repeatedly"
  
  // Continuous pulse for X
  const xPulse = Math.sin(frame * 0.2) * 0.1 + 1; // 0.9 to 1.1

  // Specific interaction punch
  const xPunch = (currentProfile?.action === 'left' && isPunching) 
    ? interpolate(progress, [0, 0.15, 0.3], [1, 1.3, 1]) 
    : 1;

  const checkPunch = (currentProfile?.action === 'fake-right' && isPunching)
    ? interpolate(progress, [0, 0.15, 0.3], [1, 1.3, 1])
    : 1;

  return (
    <div
      style={{
        position: "absolute",
        bottom: "30px",
        left: 0,
        width: "100%",
        display: "flex",
        justifyContent: "center",
        gap: "40px",
        alignItems: "center",
        zIndex: 20,
      }}
    >
      {/* X Button */}
      <div
        style={{
            width: "60px",
            height: "60px",
            backgroundColor: "#fff",
            borderRadius: "50%",
            boxShadow: "0 5px 15px rgba(0,0,0,0.1)",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            transform: `scale(${xPunch * xPulse})`,
            color: "#ff4b4b"
        }}
      >
        <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round">
            <line x1="18" y1="6" x2="6" y2="18"></line>
            <line x1="6" y1="6" x2="18" y2="18"></line>
        </svg>
      </div>

      {/* Check Button */}
      <div
        style={{
            width: "60px",
            height: "60px",
            backgroundColor: "#fff",
            borderRadius: "50%",
            boxShadow: "0 5px 15px rgba(0,0,0,0.1)",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            transform: `scale(${checkPunch})`,
            color: "#2ecc71"
        }}
      >
        <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round">
            <polyline points="20 6 9 17 4 12"></polyline>
        </svg>
      </div>
    </div>
  );
};

// ------------------------------------------------------------------
// MAIN COMPONENT
// ------------------------------------------------------------------

const DoomSwiping: React.FC<DoomSwipingProps> = ({
  backgroundColor = "#ECE7E1",
  transparentBackground = true,
  durationInSeconds = 10,
  swipeSpeedInFrames = 15,
  cardColorPalette = ["#ffadad", "#ffd6a5", "#fdffb6", "#caffbf", "#9bf6ff", "#a0c4ff", "#bdb2ff", "#ffc6ff"],
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // 1. Phone Container Dimensions (9:16 aspect ratio)
  // We want it tall. Let's base it on height.
  const phoneHeight = height * 0.85;
  const phoneWidth = (phoneHeight * 9) / 16;
  const cardWidth = phoneWidth * 0.9;
  const cardHeight = phoneHeight * 0.65;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // 2. Determine number of cards needed
  const totalFrames = durationInSeconds * fps;
  const cardCount = Math.ceil(totalFrames / swipeSpeedInFrames) + 5; // buffer

  // 3. Generate Profiles
  const profiles = useMemo(() => {
    return Array.from({ length: cardCount }).map((_, i) =>
      generateProfile(i, cardColorPalette)
    );
  }, [cardCount, cardColorPalette]);

  // 4. Determine Active Index
  const activeIndex = Math.floor(frame / swipeSpeedInFrames);

  // 5. Render visible stack
  // We only need to render activeIndex, activeIndex+1, activeIndex+2
  // Rendering too many DOM nodes hurts performance
  const visibleIndices = [activeIndex, activeIndex + 1].filter(i => i < cardCount);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        fontFamily: "Inter, sans-serif",
      }}
    >
      {/* Phone Frame */}
      <div
        style={{
          width: phoneWidth,
          height: phoneHeight,
          backgroundColor: "#ECE7E1",
          borderRadius: "30px",
          boxShadow: "0 20px 60px rgba(0,0,0,0.2)",
          position: "relative",
          overflow: "hidden",
          border: "8px solid #333",
        }}
      >
        {/* Status Bar Fake */}
        <div style={{
            position: 'absolute',
            top: 0,
            left: 0,
            width: '100%',
            height: '30px',
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            padding: '0 20px',
            zIndex: 30,
            color: '#333',
            fontSize: 12,
            fontWeight: 'bold'
        }}>
            <span>9:41</span>
            <div style={{ display: 'flex', gap: 4 }}>
                <div style={{ width: 14, height: 10, background: '#333', borderRadius: 2 }} />
                <div style={{ width: 14, height: 10, background: '#333', borderRadius: 2 }} />
                <div style={{ width: 20, height: 10, border: '2px solid #333', borderRadius: 3 }} />
            </div>
        </div>

        {/* Card Stack Area */}
        <div
            style={{
                position: 'absolute',
                top: 0,
                left: 0,
                width: '100%',
                height: '100%',
                display: 'flex',
                justifyContent: 'center',
                alignItems: 'center',
                paddingBottom: '80px' // Space for buttons
            }}
        >
            <div style={{ width: cardWidth, height: cardHeight, position: 'relative' }}>
                {visibleIndices.reverse().map((index) => (
                    <Card
                        key={index}
                        index={index}
                        profile={profiles[index]}
                        activeIndex={activeIndex}
                        swipeSpeed={swipeSpeedInFrames}
                        width={cardWidth}
                        height={cardHeight}
                    />
                ))}
            </div>
        </div>
        
        {/* Controls */}
        <ActionButtons 
            activeIndex={activeIndex} 
            swipeSpeed={swipeSpeedInFrames} 
            profiles={profiles}
        />
        
        {/* Fade Overlay for depth at bottom (optional but nice) */}
        <div style={{
            position: 'absolute',
            bottom: 0,
            left: 0,
            width: '100%',
            height: '100px',
            background: 'linear-gradient(to top, rgba(236, 231, 225, 1), rgba(236, 231, 225, 0))',
            pointerEvents: 'none',
            zIndex: 15
        }} />

      </div>
    </AbsoluteFill>
  );
};

export default DoomSwiping;